import {postCall,bindPostCall} from './post-call.js';
import {medicationReference,calculators,referenceUI,setConcentration} from './medication-ui.js';
import {kgFrom} from './calculations.js';
import {modules,causes,protocol,ages,weights,medications,energies,checklistId} from './data.js';
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',pulse:'<path d="M2 12h5l3-8 4 16 3-8h5"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7l1-7Z"/>',syringe:'<path d="m18 2 4 4m-3-1-5 5m-8 2 6 6m-9 3 3-3m0 0-1-4 9-9 5 5-9 9-4-1Z"/>',airway:'<path d="M12 2v9M8 3v8l-5 7a2 2 0 0 0 2 3h3l4-7 4 7h3a2 2 0 0 0 2-3l-5-7V3"/>',brain:'<path d="M12 5c-4-5-8 0-6 3-5 1-4 7-1 8-1 5 5 7 7 3V5Zm0 0c4-5 8 0 6 3 5 1 4 7 1 8 1 5-5 7-7 3M6 8l3 2m-4 6 4-2m9-6-3 2m4 6-4-2"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Z"/><path d="M12 8v8m-4-4h8"/>',child:'<circle cx="12" cy="5" r="3"/><path d="M5 10h14m-7-2v8m0-1-5 7m5-7 5 7"/>',book:'<path d="M12 5c-4-3-7-3-10-2v16c4-1 7 0 10 2 3-2 6-3 10-2V3c-3-1-6-1-10 2Zm0 0v16"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',reset:'<path d="M3 10a9 9 0 1 1 2 8M3 3v7h7"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>'};
const icon=(n)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.grid}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const blank=()=>({checks:{},causes:{},fields:{},started:null,elapsed:0,running:false,age:null,adultMax:'',filter:'',epiInterval:5,epiDueAt:null});
let state;try{state=Object.assign(blank(),JSON.parse(sessionStorage.getItem('wfd-encounter-v1')||'{}'));}catch{state=blank()}
let page=location.hash.slice(1)||'home',query='',modal=false;
const pageLabel=()=>({home:'Overview','post-call':'Post-call checklist',pediatric:'Pediatric reference',protocol:'Protocol library',medications:'Unusual drugs',calculators:'Dose & drip calculators'}[page]||modules.find(m=>m.id===page)?.short||'Overview');
const save=()=>{try{sessionStorage.setItem('wfd-encounter-v1',JSON.stringify(state));}catch{}};
// CSN now records narrative completion; remove the retired free-text value.
if(Object.hasOwn(state.fields,'post-csn')){delete state.fields['post-csn'];save();}
const totalChecks=()=>modules.reduce((n,m)=>n+completed(m),0);
const count=m=>m.sections.reduce((n,s)=>n+s[1].length,0);
const completed=m=>m.sections.reduce((n,section,si)=>n+section[1].filter((item,ii)=>state.checks[checklistId(m.id,si,item,ii)]).length,0);
const source=(label,p=1)=>`<a class="source" href="${protocol}#page=${p}" target="_blank" rel="noopener">${icon('book')}${esc(label)} ↗</a>`;
function nav(id,label,i){return `<button class="nav-item ${page===id?'active':''}" data-page="${id}" ${page===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${page===id?'<i></i>':''}</button>`;}
function shell(){return `<aside class="sidebar"><a href="#home" class="brand"><div class="crest">${icon('shield')}</div><span>WOODLAWN<span>FIRE DEPARTMENT</span></span></a><div class="sidebar-label">EMS FIELD GUIDE</div>${nav('home','Overview','grid')}<div class="sidebar-label space">CHECKLISTS</div>${modules.map(m=>nav(m.id,m.short,m.icon)).join('')}${nav('post-call','Post-call checklist','check')}<div class="sidebar-label space">QUICK REFERENCE</div>${nav('medications','Unusual drugs','syringe')}${nav('calculators','Dose & drip calculators','grid')}${nav('pediatric','Pediatric calculator','child')}${nav('protocol','Protocol library','book')}<div class="side-footer"><span class="status-dot"></span> 2026 Southwest Ohio<div>Version 2.9.26 · Review prototype</div></div></aside><div class="workspace"><header><div class="crumb">EMS Field Guide <span>/</span> <b>${pageLabel()}</b></div><span class="draft">REVIEW BUILD</span><button class="button small" data-action="new">${icon('plus')} New encounter</button></header><main>${page==='home'?home():page==='post-call'?postCall(state.fields,icon):page==='pediatric'?pediatric():page==='protocol'?library():page==='medications'?medicationReference(state.fields,source):page==='calculators'?calculators(state.fields,source):detail(modules.find(m=>m.id===page)||modules[0])}</main><footer>WOODLAWN FD <span>Built for a clear next step.</span><span>Prototype · Clinical validation pending</span></footer></div>${modal?dialog():''}`;}
function home(){const matches=modules.filter(m=>(m.title+' '+m.sections.map(s=>s[0]).join(' ')).toLowerCase().includes(query.toLowerCase()));return `<div class="page-heading"><div><div class="eyebrow">WOODLAWN FIRE DEPARTMENT</div><h1>Ready for the next call.</h1></div><div class="edition">${icon('shield')}<span>Southwest Ohio<b>2026 protocols</b></span></div></div><div class="review-banner"><span class="mini-badge">DRAFT</span>Review prototype · Verify before field use.<button data-page="protocol">View sources ${icon('arrow')}</button></div><div class="dashboard"><div><div class="section-top"><h2>Clinical checklists <span>06</span></h2><label class="search">${icon('search')}<input id="search" aria-label="Search checklists" placeholder="Find a checklist…" value="${esc(query)}"><kbd>/</kbd></label></div><div class="cards">${matches.map(m=>`<button class="module-card ${m.color}" data-page="${m.id}"><div class="card-top"><div class="module-icon">${icon(m.icon)}</div><span>${m.tag}</span>${icon('arrow')}</div><h3>${m.title}</h3><div class="card-bottom"><span>${completed(m)?`${completed(m)} / ${count(m)} complete`:`${count(m)} checklist steps`}</span><span>Open checklist ↗</span></div></button>`).join('')||'<p class="empty">No matching checklist. Try “airway” or “trauma”.</p>'}</div><button class="quick-tool post-call-launch" data-page="post-call">${icon('check')}<span><b>Post-call checklist</b><small>Call closeout + supplies needed for restock</small></span>${icon('arrow')}</button><div class="quick-tool-grid"><button class="quick-tool red" data-page="medications">${icon('syringe')}<span><b>Unusual drugs</b><small>Less familiar drugs + protocol</small></span>${icon('arrow')}</button><button class="quick-tool blue" data-page="calculators">${icon('grid')}<span><b>Dose & drip calculators</b><small>Volumes, rates, kg ↔ lb</small></span>${icon('arrow')}</button></div><button class="pediatric-banner" data-page="pediatric"><div class="module-icon">${icon('child')}</div><div><span class="eyebrow">SMALL PATIENTS. CLEAR NUMBERS.</span><h3>Pediatric quick reference</h3></div><span class="round-arrow">${icon('arrow')}</span></button></div><aside class="right-rail"><section class="panel encounter"><div class="section-top"><h2>Current encounter</h2><span class="tiny-dot"></span></div><p class="muted">Progress stays in this browser tab.</p><div class="encounter-stat"><strong>${String(totalChecks()).padStart(2,'0')}</strong><span>steps checked<br>across your checklists</span></div><div class="thin-progress"><span style="width:${totalChecks()/modules.reduce((n,m)=>n+count(m),0)*100}%"></span></div><div class="encounter-links">${modules.filter(m=>completed(m)).map(m=>`<button data-page="${m.id}">${m.short}<span>${completed(m)}/${count(m)} ${icon('arrow')}</span></button>`).join('')||'<p>Open a checklist to get started.</p>'}</div></section>${timerPanel()}<section class="rail-note">${source('OPEN FULL PROTOCOL')}</section></aside></div>`;}
function timerPanel(){return `<section class="panel timer"><div class="section-top"><h2>${icon('clock')} Event timer</h2><span class="timer-label">ELAPSED</span></div><div class="timer-digits" role="timer">${timerText()}</div><div class="timer-actions"><button class="button primary" data-action="timer">${state.running?'Pause':'Start timer'}</button><button class="button icon-button" data-action="reset-timer" aria-label="Reset timer">${icon('reset')}</button></div><p class="muted">Manual elapsed timer; no clinical alarms.</p></section>`;}
function timerText(){const ms=state.elapsed+(state.running?Date.now()-state.started:0);const s=Math.floor(ms/1000);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function epiInterval(){return [3,4,5].includes(Number(state.epiInterval))?Number(state.epiInterval):5;}
function epiSeconds(){return state.epiDueAt===null?epiInterval()*60:Math.max(0,Math.ceil((state.epiDueAt-Date.now())/1000));}
function epiText(){const s=epiSeconds();return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function epiStatus(){return state.epiDueAt===null?'Ready after first dose':epiSeconds()===0?'NEXT DOSE DUE':'Until next dose';}
function epiPanel(){return `<section class="epi-panel ${state.epiDueAt!==null&&epiSeconds()===0?'due':''}" aria-labelledby="epi-title">
  <div class="epi-heading"><h2 id="epi-title">${icon('clock')} Epi dose timer</h2>${source('EPI PROTOCOL · C300',75)}</div>
  <div class="epi-body"><div><div class="epi-digits" role="timer" aria-label="Time until next epinephrine dose">${epiText()}</div><p class="epi-status" role="status" aria-live="polite">${epiStatus()}</p></div>
    <div class="epi-controls"><label class="field">Dose interval<select id="epi-interval" ${state.epiDueAt!==null?'disabled':''}>${[3,4,5].map(n=>`<option value="${n}" ${epiInterval()===n?'selected':''}>${n} minutes${n===5?' (default)':''}</option>`).join('')}</select></label>
      <button class="button epi-start" data-action="epi-dose">Epi given · ${state.epiDueAt===null?'start':'restart'} ${epiInterval()} min</button>
      <button class="button" data-action="clear-epi" ${state.epiDueAt===null?'disabled':''}>Clear timer</button>
    </div>
  </div><p class="epi-note">Start after administration. Repeat per arrest protocol (3–5 min). Visual reminder only.</p>
</section>`;}
function checklistRow(m,item,si,ii){
  const entry=typeof item==='string'?{text:item}:item;
  const id=checklistId(m.id,si,item,ii);
  return `<div class="check-row ${state.checks[id]?'checked':''}">
    <label class="check-control"><input type="checkbox" data-check="${id}" ${state.checks[id]?'checked':''}><span class="custom-check">${icon('check')}</span><span class="check-copy"><span>${esc(entry.text)}</span>${entry.note?`<small>${esc(entry.note)}</small>`:''}</span></label>
    ${entry.protocol||entry.tool?`<div class="check-links">${entry.protocol?source(...entry.protocol):''}${entry.tool?`<button class="button small" data-page="${entry.tool[0]}">${esc(entry.tool[1])} ${icon('arrow')}</button>`:''}</div>`:''}
  </div>`;
}
function detail(m){return `<button class="back" data-page="home">← All checklists</button>
  <div class="page-heading detail-heading"><div><div class="eyebrow ${m.color}">${m.tag}</div><h1>${m.title}</h1></div><div class="large-icon ${m.color}">${icon(m.icon)}</div></div>
  <nav class="protocol-links" aria-label="${esc(m.title)} protocols"><b>PROTOCOLS</b>${m.refs.map(ref=>source(...ref)).join('')}</nav>
  <div class="detail-layout"><div>
    ${m.id==='sick'?epiPanel():''}
    ${m.id==='cardio'?'<div class="callout amber"><b>SYNC: confirm R-wave markers before every shock.</b>Pulseless VF / VT: unsynchronized defibrillation.</div>':''}
    ${m.id==='sedation'?'<div class="callout purple"><b>Use the indication-specific protocol.</b>Confirm required medical-control orders.</div>':''}
    ${m.id==='ams'?amsFields():''}
    <div class="checklist-progress"><b>${completed(m)} of ${count(m)} complete</b><span>${Math.round(completed(m)/count(m)*100)}%</span><div class="thin-progress"><span style="width:${completed(m)/count(m)*100}%"></span></div></div>
    ${m.sections.map((section,si)=>`<section class="check-section"><h2><span>${String(si+1).padStart(2,'0')}</span>${section[0]}</h2>${section[1].map((item,ii)=>checklistRow(m,item,si,ii)).join('')}</section>`).join('')}
    ${m.id==='ams'?amsCauses():''}
    ${m.id==='sick'?`<section class="panel"><h2>Reversible causes</h2><div class="cause-tags">${['Hypoxia','Hypovolemia','Acidosis','Hypo- / hyperkalemia','Hypothermia','Tension pneumothorax','Tamponade','Thrombosis','Toxins','Trauma'].map(c=>`<span>${c}</span>`).join('')}</div></section>`:''}
  </div><aside class="right-rail">${timerPanel()}<section class="panel"><h2>Related tools</h2>${(m.id==='ams'?['sick','trauma']:m.id==='intubation'?['sedation','sick']:['intubation','ams']).map(id=>{const r=modules.find(x=>x.id===id);return `<button class="tool-link" data-page="${id}">${icon(r.icon)}${r.short}${icon('arrow')}</button>`}).join('')}<button class="tool-link" data-page="medications">${icon('syringe')}Unusual drugs${icon('arrow')}</button><button class="tool-link" data-page="calculators">${icon('grid')}Dose & drip calculators${icon('arrow')}</button><button class="tool-link" data-page="pediatric">${icon('child')}Pediatric reference${icon('arrow')}</button></section></aside></div>`;}
function field(id,label,type='text',placeholder=''){return `<label class="field">${label}<input type="${type}" data-field="${id}" value="${esc(state.fields[id])}" placeholder="${placeholder}"></label>`;}
function amsFields(){return `<section class="panel ams-history"><div class="section-top"><h2>Establish the timeline</h2><span class="mini-badge">AMS</span></div><div class="fields">${field('lkw','Last known well · local date & time','datetime-local')}${field('onset','Symptom onset · local date & time','datetime-local')}${field('baseline','Baseline mental status','text','Usual orientation / function')}${field('glucose','Blood glucose · mg/dL','number','Value')}</div><label class="inline-check"><input type="checkbox" data-field-check="lkwUnknown" ${state.fields.lkwUnknown?'checked':''}> Last known well is unknown</label><p class="muted">Use this prototype with simulated data. Entries stay in this tab and clear with New encounter.</p></section>`;}
function amsCauses(){return `<section class="panel differential"><h2>Work through possible causes</h2><p class="muted">Statuses record your assessment; they are not an automated diagnosis.</p>${causes.map(([id,title,desc])=>`<div class="cause-row"><div><h3>${title}</h3><p>${desc}</p></div><div class="segments" role="group" aria-label="${title}">${[['unassessed','Unassessed'],['in','Ruled in'],['out','Ruled out']].map(([v,l])=>`<button data-cause="${id}" data-value="${v}" aria-pressed="${(state.causes[id]||'unassessed')===v}" class="${(state.causes[id]||'unassessed')===v?'selected '+v:''}">${l}</button>`).join('')}</div></div>`).join('')}</section>`;}
function pediatric(){const i=state.age,w=i===null?null:weights[i],energy=energies(i,Number(state.adultMax));const filtered=medications.filter(m=>(m.name+' '+m.route+' '+m.concentration).toLowerCase().includes(state.filter.toLowerCase()));return `<div class="page-heading"><div><div class="eyebrow teal">PEDIATRIC QUICK REFERENCE</div><h1>Small patients. Clear numbers.</h1></div><div class="large-icon teal">${icon('child')}</div></div><div class="callout amber"><b>Estimated age is a lookup, not a measured weight.</b> Appendix J estimates; no interpolation. Confirm actual weight / validated length-based estimate and indication.</div><section class="panel age-panel"><div class="section-top"><h2>01 <span>Select the reference age</span></h2>${source('Appendix J · pp. 237–238',237)}</div><div class="age-grid">${ages.map((a,n)=>`<button data-age="${n}" class="${i===n?'selected':''}" aria-pressed="${i===n}"><b>${a}</b><span>${weights[n]} kg est.</span></button>`).join('')}</div></section>${i===null?'<div class="empty-state">'+icon('child')+'<h2>Choose an age to open its reference card.</h2><p>Medication dose, concentration, route, and volume appear together.</p></div>':`<div class="peds-summary"><section><span>REFERENCE AGE</span><b>${ages[i]}</b></section><section><span>ESTIMATED WEIGHT</span><b>${w} <small>kg</small></b></section><section><span>LOW SYSTOLIC · APP J</span><b>${['60–70','70','70–75','75–80','80','80','85','85','90'][i]} <small>mmHg</small></b></section><section><span>PULSE · APP J</span><b>${['100–180','100–180','90–160','80–140','70–130','70–130','60–120','60–120','60–120'][i]} <small>/min</small></b></section></div><section class="panel energy-panel"><div class="section-top"><h2>${icon('bolt')} Defibrillation · VF / pulseless VT</h2>${source('P601 · p. 152',152)}</div><label class="field cap-field">Adult energy ceiling for your device / protocol<select id="adult-max"><option value="">Select the applicable limit</option><option value="200" ${state.adultMax==='200'?'selected':''}>200 J</option><option value="360" ${state.adultMax==='360'?'selected':''}>360 J</option></select></label><div class="energy-grid"><div><span>INITIAL · 2 J/kg</span><b>${energy?energy[0]+' J':'—'}</b></div><div><span>SECOND · 4 J/kg</span><b>${energy?energy[1]+' J':'—'}</b></div><div><span>SUBSEQUENT · 4–10 J/kg</span><b>${energy?energy[1]+'–'+energy[2]+' J':'—'}</b></div></div><p class="muted">${energy?'Based on '+w+' kg estimated weight. Rounded up and capped at the selected adult dose.':'Select an adult energy ceiling to calculate capped values.'} Newborn resuscitation follows P600.</p><details><summary>Synchronized cardioversion · PSVT</summary><p>P604: medical-control order required. At ${w} kg estimated weight: ${Math.ceil(w*.5)} J → ${w} J → ${w*2} J. Confirm SYNC before each shock.</p>${source('P604 · p. 155',155)}</details></section><section class="panel medication-panel"><div class="section-top"><h2>Medication & fluid reference <span>${medications.length}</span></h2><label class="search">${icon('search')}<input id="med-search" aria-label="Filter medications" placeholder="Find medication or route…" value="${esc(state.filter)}"></label></div><p class="muted">Verify indication, age limits, repeat dosing, and orders. Table values take precedence. Missing dose: N/A.</p><div class="table-scroll"><table><thead><tr><th>Medication / indication</th><th>Route · concentration</th><th>Dose</th><th>Volume</th></tr></thead><tbody>${filtered.map(m=>`<tr><td><b>${m.name}</b>${m.note?`<details><summary>Reference note</summary><p>${m.note}</p></details>`:''}<a class="table-source" href="${protocol}#page=${m.page}" target="_blank" rel="noopener">PROTOCOL · App J ${m.page} ↗</a></td><td>${m.route}<small>${m.concentration}</small></td><td class="dose">${m.doses[i]===null?'<span class="na">N/A</span>':`${m.doses[i]} <small>${m.doseUnits?.[i]??m.unit}</small>`}</td><td>${m.doses[i]===null?'N/A':m.volumes?m.volumes[i]+' mL':m.unit==='mL'?m.doses[i]+' mL':'N/A'}</td></tr>`).join('')||'<tr><td colspan="4">No matching medication.</td></tr>'}</tbody></table></div></section>`}`;}
function library(){return `<div class="page-heading"><div><div class="eyebrow">SOURCE OF TRUTH</div><h1>Protocol library</h1></div></div><section class="protocol-hero"><div>${icon('book')}<h2>Southwest Ohio EMS Protocols</h2><p>Academy of Medicine of Cincinnati · 2026</p><span>Version 2.9.26 · Supplied by you</span></div>${source('Open governing protocol')}</section><section class="panel"><h2>Module references</h2>${modules.map(m=>`<div class="library-row"><div><b>${m.title}</b><p>${m.source}</p></div><div class="library-links">${m.refs.map(ref=>source(...ref)).join('')}</div></div>`).join('')}<div class="library-row"><div><b>Pediatric medication and energy references</b><p>Appendix J · P601 · P604</p></div>${source('Open Appendix J',237)}</div></section><section class="panel"><h2>Review notes</h2><ul class="review-list"><li>Workflow structure is adapted from your sick patient, cardioversion, intubation, trauma, and AMS checklists. These prompts are not a complete protocol.</li><li>The provided pediatric reference includes 2025 tables. This prototype uses the linked 2026 Appendix J columns.</li><li>Pediatric table entries take precedence where references differ; doses and volumes are displayed as printed. Missing entries show N/A.</li><li>Age presets are estimates. The pediatric age table remains an estimate; the medication reference calculates from entered patient weight under specific protocols.</li><li>Unusual drugs and stock volumes are indication-specific. Confirm concentrations and department clinical approval before field use.</li></ul></section><section class="panel"><h2>About this prototype</h2><p>Checklists, AMS assessment, timer, and pediatric selection share one encounter in this browser tab. No patient account, backend patient record, or offline guarantee is provided. Use simulated data while reviewing. New encounter clears tab-stored entries.</p></section>`;}
function dialog(){return `<div class="modal-backdrop"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="module-icon red">${icon('reset')}</div><h2 id="dialog-title">Start a new encounter?</h2><p>This clears all checklist progress, AMS entries, pediatric selections, calculator inputs, post-call closeout, and both timers in this tab. Your supplies needed list is kept for restocking.</p><div><button class="button" data-action="cancel">Keep current encounter</button><button class="button primary" data-action="confirm-new">Clear & start new</button></div></section></div>`;}
function rememberReferenceOpen(){document.querySelectorAll('[data-ref-open]').forEach(el=>{if(el.open)referenceUI.open.add(el.dataset.refOpen);else referenceUI.open.delete(el.dataset.refOpen);});}
function render(){rememberReferenceOpen();document.querySelector('#app').innerHTML=shell();document.title=`${pageLabel()} · Woodlawn FD`;if(state.fields.lkwUnknown){const lkw=document.querySelector('[data-field="lkw"]');if(lkw)lkw.disabled=true;}if(modal)document.querySelector('[data-action="cancel"]').focus();}
function refreshReference(el){
  const id=el.id,y=window.scrollY,selection=el.type==='text'?el.selectionStart:null;
  render();window.scrollTo(0,y);const next=document.getElementById(id);if(next){next.focus({preventScroll:true});if(selection!==null&&next.type==='text')next.setSelectionRange(selection,selection);}
}
function go(id){page=id;location.hash=id;render();window.scrollTo(0,0);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page)go(b.dataset.page);if(b.dataset.useWeight){const kg=kgFrom(state.fields['convert-value'],state.fields['convert-unit']??'lb');if(kg!==null){state.fields['ref-weight']=String(kg);state.fields['ref-weight-unit']='kg';save();render();}}if(b.dataset.age!==undefined){state.age=Number(b.dataset.age);save();render();}if(b.dataset.cause){state.causes[b.dataset.cause]=b.dataset.value;save();render();}switch(b.dataset.action){case 'new':modal=true;render();break;case 'cancel':modal=false;render();break;case 'confirm-new':state=blank();referenceUI.search='';referenceUI.protocol='';referenceUI.category='';referenceUI.open.clear();save();modal=false;go('home');break;case 'timer':if(state.running){state.elapsed+=Date.now()-state.started;state.running=false;state.started=null;}else{state.started=Date.now();state.running=true;}save();render();break;case 'epi-dose':state.epiDueAt=Date.now()+epiInterval()*60_000;save();render();break;case 'clear-epi':state.epiDueAt=null;save();render();break;case 'reset-timer':state.elapsed=0;state.running=false;state.started=null;save();render();break;}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.refField&&el.tagName==='SELECT'){state.fields[el.dataset.refField]=el.value;save();refreshReference(el);}if(el.dataset.stock){setConcentration(el.dataset.stock,el.value);refreshReference(el);}if(el.id==='reference-protocol'||el.id==='reference-category'){referenceUI[el.id==='reference-protocol'?'protocol':'category']=el.value;refreshReference(el);}if(el.dataset.check){state.checks[el.dataset.check]=el.checked;save();const y=window.scrollY;render();window.scrollTo(0,y);document.querySelector(`[data-check="${el.dataset.check}"]`)?.focus({preventScroll:true});}if(el.dataset.fieldCheck){state.fields[el.dataset.fieldCheck]=el.checked;if(el.dataset.fieldCheck==='lkwUnknown'&&el.checked)state.fields.lkw='';save();const y=window.scrollY;render();window.scrollTo(0,y);document.querySelector(`[data-field-check="${el.dataset.fieldCheck}"]`)?.focus({preventScroll:true});}if(el.id==='epi-interval'&&state.epiDueAt===null){state.epiInterval=Number(el.value);save();render();}if(el.id==='adult-max'){state.adultMax=el.value;save();render();}});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.refField&&el.tagName==='INPUT'){state.fields[el.dataset.refField]=el.value;save();refreshReference(el);}if(el.dataset.stockCustom){setConcentration(el.dataset.stockCustom,el.value,true);refreshReference(el);}if(el.id==='reference-search'){referenceUI.search=el.value;refreshReference(el);}if(el.dataset.field){state.fields[el.dataset.field]=el.value;save();}if(el.id==='search'||el.id==='med-search'){const pos=el.selectionStart;if(el.id==='search')query=el.value;else{state.filter=el.value;save();}render();const replacement=document.getElementById(el.id);replacement.focus();replacement.setSelectionRange(pos,pos);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){modal=false;render();}if(e.key==='Tab'&&modal){const focusable=[...document.querySelectorAll('.dialog button')];if(e.shiftKey&&document.activeElement===focusable[0]){e.preventDefault();focusable.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===focusable.at(-1)){e.preventDefault();focusable[0].focus();}}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){const s=document.getElementById('supply-search')||document.getElementById('search')||document.getElementById('med-search');if(s){e.preventDefault();s.focus();}}});
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'home';render();});
setInterval(()=>{
  document.querySelectorAll('.timer-digits').forEach(e=>e.textContent=timerText());
  const epi=document.querySelector('.epi-panel');
  if(epi){epi.querySelector('.epi-digits').textContent=epiText();const status=epi.querySelector('.epi-status');if(status.textContent!==epiStatus())status.textContent=epiStatus();epi.classList.toggle('due',state.epiDueAt!==null&&epiSeconds()===0);}
},250);
bindPostCall(render);
render();
